mapper.select:
select count(1)
from renyuan_laoren
where huli_renyuan_id = #{huliRenyuanId}
  and laoren_id = #{laorenId}
  and zhuangtai = '服务中'

select hj.id, hj.laoren_id as laorenId, l.xingming as laorenXingming, hj.xiangmu_id as xiangmuId, x.xiangmu_mingcheng as xiangmuMingcheng, hj.huli_shijian as huliShijian, hj.huli_shuliang as huliShuliang, hj.huli_neirong as huliNeirong, hj.laoren_fankui as laorenFankui, hj.zhuangtai from huli_jilu hj join laoren_xinxi l on hj.laoren_id = l.id join huli_xiangmu x on hj.xiangmu_id = x.id join renyuan_laoren rl on hj.laoren_id = rl.laoren_id where hj.huli_renyuan_id = #{huliRenyuanId} and rl.huli_renyuan_id = #{huliRenyuanId} and rl.zhuangtai = '服务中' and hj.zhuangtai != '取消'
and hj.laoren_id = #{laorenId}
order by hj.huli_shijian desc, hj.id desc

mapper.update:
update huli_jilu
set zhuangtai = '取消'
where id = #{id}
  and huli_renyuan_id = #{huliRenyuanId}

mapper.select:
select jj.id, jj.laoren_id as laorenId, l.xingming as laorenXingming, jj.jiance_shijian as jianceShijian, jj.tiwen, jj.gaoya, jj.diya, jj.xinlv, jj.xueyang, jj.xuetang, jj.qingkuang from jiankang_jiance jj join laoren_xinxi l on jj.laoren_id = l.id join renyuan_laoren rl on jj.laoren_id = rl.laoren_id where jj.huli_renyuan_id = #{huliRenyuanId} and rl.huli_renyuan_id = #{huliRenyuanId} and rl.zhuangtai = '服务中'
and jj.laoren_id = #{laorenId}
order by jj.jiance_shijian desc, jj.id desc

mapper.insert:
insert into jiankang_jiance (
    laoren_id, huli_renyuan_id, jiance_shijian,
    tiwen, gaoya, diya, xinlv, xueyang, xuetang, qingkuang
) values (
    #{laorenId}, #{huliRenyuanId}, coalesce(#{jianceShijian}, now()),
    #{tiwen}, #{gaoya}, #{diya}, #{xinlv}, #{xueyang}, #{xuetang}, #{qingkuang}
)

mapper.select:
select yj.id, yj.laoren_id as laorenId, l.xingming as laorenXingming, yj.yaopin_id as yaopinId, yp.yaopin_mingcheng as yaopinMingcheng, yp.guige, yj.kaishi_riqi as kaishiRiqi, yj.jieshu_riqi as jieshuRiqi, yj.yongfa, yj.meiri_cishu as meiriCishu, yj.meici_yongliang as meiciYongliang, yj.yongyao_shijian as yongyaoShijian, yj.yizhu, yj.zhuangtai from yongyao_jihua yj join yaopin_xinxi yp on yj.yaopin_id = yp.id join laoren_xinxi l on yj.laoren_id = l.id join renyuan_laoren rl on yj.laoren_id = rl.laoren_id where rl.huli_renyuan_id = #{huliRenyuanId} and rl.zhuangtai = '服务中'
and yj.laoren_id = #{laorenId}
order by yj.id desc

select fj.id, fj.jihua_id as jihuaId, fj.laoren_id as laorenId, l.xingming as laorenXingming, fj.yaopin_id as yaopinId, yp.yaopin_mingcheng as yaopinMingcheng, fj.jihua_shijian as jihuaShijian, fj.shiji_shijian as shijiShijian, fj.zhixing_zhuangtai as zhixingZhuangtai, fj.beizhu from fuyao_jilu fj join laoren_xinxi l on fj.laoren_id = l.id join yaopin_xinxi yp on fj.yaopin_id = yp.id join renyuan_laoren rl on fj.laoren_id = rl.laoren_id where fj.huli_renyuan_id = #{huliRenyuanId} and rl.huli_renyuan_id = #{huliRenyuanId} and rl.zhuangtai = '服务中'
and fj.laoren_id = #{laorenId}
order by fj.jihua_shijian desc, fj.id desc

mapper.insert:
insert into fuyao_jilu (
    jihua_id, laoren_id, yaopin_id, huli_renyuan_id,
    jihua_shijian, shiji_shijian, zhixing_zhuangtai, beizhu
) values (
    #{jihuaId}, #{laorenId}, #{yaopinId}, #{huliRenyuanId},
    coalesce(#{jihuaShijian}, now()), #{shijiShijian}, coalesce(#{zhixingZhuangtai}, '已服药'), #{beizhu}
)

mapper.select:
select ws.id, ws.laoren_id as laorenId, l.xingming as laorenXingming, ws.waichu_shiyou as waichuShiyou, ws.waichu_shijian as waichuShijian, ws.yuji_huiyuan_shijian as yujiHuiyuanShijian, ws.peitong_ren as peitongRen, ws.peitong_dianhua as peitongDianhua, ws.shenqing_ren_id as shenqingRenId, coalesce(ws.shenqing_ren_leixing, '历史数据') as shenqingRenLeixing, coalesce(ws.shenqing_ren_xingming, '') as shenqingRenXingming, ws.shenpi_zhuangtai as shenpiZhuangtai, ws.shenpi_yijian as shenpiYijian from waichu_shenqing ws join laoren_xinxi l on ws.laoren_id = l.id join renyuan_laoren rl on ws.laoren_id = rl.laoren_id where ws.huli_renyuan_id = #{huliRenyuanId} and rl.huli_renyuan_id = #{huliRenyuanId} and rl.zhuangtai = '服务中' and coalesce(ws.shanchu_zhuangtai, '正常') = '正常'
and ws.laoren_id = #{laorenId}
order by ws.waichu_shijian desc, ws.id desc

select ts.id, ts.laoren_id as laorenId, l.xingming as laorenXingming, ts.tuizhu_leixing as tuizhuLeixing, ts.tuizhu_yuanyin as tuizhuYuanyin, ts.tuizhu_shijian as tuizhuShijian, ts.shenqing_ren_id as shenqingRenId, coalesce(ts.shenqing_ren_leixing, '历史数据') as shenqingRenLeixing, coalesce(ts.shenqing_ren_xingming, '') as shenqingRenXingming, ts.shenpi_zhuangtai as shenpiZhuangtai, ts.shenpi_yijian as shenpiYijian from tuizhu_shenqing ts join laoren_xinxi l on ts.laoren_id = l.id join renyuan_laoren rl on ts.laoren_id = rl.laoren_id where ts.huli_renyuan_id = #{huliRenyuanId} and rl.huli_renyuan_id = #{huliRenyuanId} and rl.zhuangtai = '服务中' and coalesce(ts.shanchu_zhuangtai, '正常') = '正常'
and ts.laoren_id = #{laorenId}
order by ts.tuizhu_shijian desc, ts.id desc
